    (∫ t : ℝ in Ioi 0, Real.exp (lam * t) * betaTwoCallCut k t) =
      ∫ t : ℝ in 0..(k : ℝ), Real.exp (lam * t) * betaTwoCall k t

theorem betaOneExpCallTransform_le (k : ℕ) (hk : 1 ≤ k) {lam : ℝ}
    (hlam : lam < 1) :
    expCallTransform 1 lam (betaOneCallCut k) ≤ (1 - lam)⁻¹

private lemma gammaTwo_weighted_integral {lam : ℝ} (hlam : lam < 1) :
    (∫ t : ℝ in Ioi 0, Real.exp (lam * t) * gammaTwoCall t) =
      (1 - lam)⁻¹ ^ 2 + 2 * (1 - lam)⁻¹

theorem betaTwoExpCallTransform_le (k : ℕ) (hk : 3 ≤ k) {lam : ℝ}
    (hlam : lam < 1) :
    expCallTransform 2 lam (betaTwoCallCut k) ≤ (1 - lam)⁻¹ ^ 2

theorem winnerBetaExpMoment_le (k : ℕ) (hk : 2 ≤ k) {lam : ℝ}
    (hlam : lam < 1) :
    betaOneExpMoment k lam ≤ (1 - lam)⁻¹

theorem loserBetaExpMoment_le (k : ℕ) (hk : 3 ≤ k) {lam : ℝ}
    (hlam : lam < 1) :
    betaTwoExpMoment k lam ≤ (1 - lam)⁻¹ ^ 2

private lemma betaOneTailAnti_hasDerivAt (k : ℕ) (hk : 2 ≤ k) (x : ℝ) :
    HasDerivAt (fun y : ℝ => -(1 - y / (k : ℝ)) ^ (k - 1))
      (SharedRace.betaOneDensity k x) x
